mapper.insert:
INSERT INTO image_board
(
  board_no      -- 시퀀스 채번
, title         -- 제목
, content       -- 내용(HTML)
, thumb_file_no -- 썸네일 파일번호
, hit           -- 조회수
, use_yn        -- 사용여부
, reg_date      -- 등록일
, reg_user      -- 등록자
)
VALUES
(
  #{boardNo}
, #{title}
, #{content}
, #{thumbFileNo}
, 0
, 'Y'
, NOW()
, #{regUser}
)

mapper.update:
UPDATE image_board
SET    title         = #{title}
     , content       = #{content}
     , thumb_file_no = #{thumbFileNo}
     , mod_date      = NOW()
     , mod_user      = #{modUser}
WHERE  board_no = #{boardNo}

UPDATE image_board
SET    use_yn   = 'N'
     , mod_date = NOW()
     , mod_user = #{modUser}
WHERE  board_no = #{boardNo}

UPDATE image_board
SET    hit = hit + 1
WHERE  board_no = #{boardNo}

mapper.insert:
INSERT INTO file_master
(
  board_no   -- 임시: 0 (게시글 저장 시 activateFiles로 확정)
, file_path  -- 파일 저장 경로
, file_name  -- 서버 저장 파일명 (UUID 기반)
, org_name   -- 원본 파일명
, file_ext   -- 파일 확장자
, file_size  -- 파일 크기 (bytes)
, sort_ord   -- 정렬 순서
, use_yn     -- 임시: 'N' (게시글 저장 시 'Y'로 변경)
, reg_user   -- 등록자
)
VALUES
(
  0
, #{filePath}
, #{fileName}
, #{orgName}
, #{fileExt}
, #{fileSize}
, #{sortOrd}
, 'N'
, #{regUser}
)

INSERT INTO file_master
(
  board_no   -- 게시글번호
, file_path  -- 파일 저장 경로
, file_name  -- 서버 저장 파일명 (UUID 기반)
, org_name   -- 원본 파일명
, file_ext   -- 파일 확장자
, file_size  -- 파일 크기 (bytes)
, sort_ord   -- 정렬 순서
, use_yn     -- 사용여부
, reg_user   -- 등록자
)
VALUES
(
  #{boardNo}
, #{filePath}
, #{fileName}
, #{orgName}
, #{fileExt}
, #{fileSize}
, #{sortOrd}
, 'Y'
, #{regUser}
)

mapper.update:
UPDATE file_master
SET    use_yn = 'N'
WHERE  file_no = #{fileNo}
